import{_ as d,o as r,c as e,a3 as a}from"./chunks/framework.Ba39LDvt.js";const p=JSON.parse('{"title":"会议与期刊地图","description":"按电路、架构、EDA、器件与光电方向认识 IC 学术共同体和投稿节奏。","frontmatter":{"title":"会议与期刊地图","description":"按电路、架构、EDA、器件与光电方向认识 IC 学术共同体和投稿节奏。"},"headers":[],"relativePath":"research-guide/venues.md","filePath":"research-guide/venues.md","lastUpdated":1795513256000}'),o={name:"research-guide/venues.md"};function i(n,t,h,s,l,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="会议与期刊地图" tabindex="-1">会议与期刊地图 <a class="header-anchor" href="#会议与期刊地图" aria-label="Permalink to &quot;会议与期刊地图&quot;">​</a></h1><p>会议与期刊是理解一个领域在讨论什么的入口，不是选题的替代品。刚入门时，可沿<a href="/shanghaitech-ic-wiki-dev.github.io/research/">科研方向</a>找近年教程、邀请报告和代表论文，再建立自己的关键词与作者列表。</p><div class="warning custom-block"><p class="custom-block-title">时间与“级别”说明</p><p>下表的级别指领域定位，不是统一排行榜，也不等同于 CCF A/B/C。月份仅列较稳定的常见投稿窗口，通常是会议举办前一年的月份；未列月份表示应直接查当届征稿通知（Call for Papers，CFP）。摘要注册、正文、补充材料和特殊赛道可能有不同截止时间，时区也不同。</p></div><h2 id="固态电路" tabindex="-1">固态电路 <a class="header-anchor" href="#固态电路" aria-label="Permalink to &quot;固态电路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>会议 / 期刊</th><th>领域</th><th>级别 / 定位</th><th>截稿大致时间段</th></tr></thead><tbody><tr><td>ISSCC</td><td>模拟、数字、射频、存储与系统芯片</td><td>固态电路旗舰会议，重视芯片实测</td><td>通常 9 月</td></tr><tr><td>IEEE Symposium on VLSI Technology and Circuits</td><td>器件技术与电路</td><td>领域旗舰会议，含技术与电路方向</td><td>通常 11–12 月，查当届</td></tr><tr><td>CICC</td><td>定制集成电路</td><td>重要电路会议</td><td>查当届 CFP</td></tr><tr><td>ESSCIRC / ESSERC</td><td>欧洲固态电路与电子研究</td><td>重要会议；近年组织名称与赛道有调整</td><td>查当届 CFP</td></tr><tr><td>A-SSCC</td><td>亚洲固态电路</td><td>重要电路会议</td><td>查当届 CFP</td></tr><tr><td>JSSC</td><td>固态电路</td><td>IEEE 代表性期刊，常有会议扩展稿</td><td>常规稿滚动，专刊另查</td></tr><tr><td>TCAS-I / TCAS-II</td><td>电路与系统理论、实现及简报</td><td>IEEE Transactions 系列期刊</td><td>常规稿滚动</td></tr><tr><td>TVLSI</td><td>超大规模集成电路与系统</td><td>IEEE Transactions 系列期刊</td><td>常规稿滚动</td></tr></tbody></table><p>JSSC 是 <em>IEEE Journal of Solid-State Circuits</em>；TCAS 是 <em>IEEE Transactions on Circuits and Systems</em>；TVLSI 是 <em>IEEE Transactions on Very Large Scale Integration Systems</em>。投稿前确认是否要求硅片实测、如何报告测试条件，以及扩展稿相对会议稿的新增贡献。</p><h2 id="体系结构与-eda" tabindex="-1">体系结构与 EDA <a class="header-anchor" href="#体系结构与-eda" aria-label="Permalink to &quot;体系结构与 EDA&quot;">​</a></h2><table tabindex="0"><thead><tr><th>会议 / 期刊</th><th>领域</th><th>级别 / 定位</th><th>截稿大致时间段</th></tr></thead><tbody><tr><td>ISCA</td><td>计算机体系结构</td><td>体系结构旗舰会议</td><td>通常 11 月</td></tr><tr><td>MICRO</td><td>微体系结构</td><td>体系结构旗舰会议</td><td>通常 4 月</td></tr><tr><td>HPCA</td><td>高性能体系结构</td><td>体系结构旗舰会议</td><td>通常 7–8 月</td></tr><tr><td>ASPLOS</td><td>架构、编程语言与操作系统交叉</td><td>系统交叉旗舰会议</td><td>可能多轮，查当届</td></tr><tr><td>DAC</td><td>电子设计自动化及系统设计</td><td>EDA 旗舰会议</td><td>研究论文常见 11 月左右</td></tr><tr><td>ICCAD</td><td>计算机辅助设计</td><td>EDA 旗舰会议</td><td>研究论文常见 5 月左右</td></tr><tr><td>DATE</td><td>设计、自动化与测试</td><td>重要 EDA 与系统会议</td><td>常见 9 月左右</td></tr><tr><td>ASP-DAC</td><td>亚太设计自动化</td><td>重要 EDA 会议</td><td>常见 7 月左右</td></tr><tr><td>TCAD</td><td>集成电路与系统 CAD</td><td>IEEE Transactions 系列代表性期刊</td><td>常规稿滚动</td></tr></tbody></table><p>TCAD 全称为 <em>IEEE Transactions on Computer-Aided Design of Integrated Circuits and Systems</em>。架构论文关注工作负载、模拟器验证、系统瓶颈及比较公平性；EDA 论文关注算法、运行时间、约束、公开基准及可扩展性。同样叫“芯片优化”，适合的共同体可能完全不同。</p><h2 id="fpga、器件与光电" tabindex="-1">FPGA、器件与光电 <a class="header-anchor" href="#fpga、器件与光电" aria-label="Permalink to &quot;FPGA、器件与光电&quot;">​</a></h2><table tabindex="0"><thead><tr><th>会议 / 期刊</th><th>领域</th><th>级别 / 定位</th><th>截稿大致时间段</th></tr></thead><tbody><tr><td>ACM FPGA</td><td>FPGA 架构、工具与应用</td><td>FPGA 代表性会议</td><td>查当届 CFP</td></tr><tr><td>FCCM</td><td>定制计算与 FPGA 系统</td><td>重要会议</td><td>查当届 CFP</td></tr><tr><td>FPL</td><td>现场可编程逻辑与应用</td><td>重要会议</td><td>查当届 CFP</td></tr><tr><td>IEDM</td><td>半导体器件与工艺</td><td>器件旗舰会议</td><td>常见 7–8 月，晚新闻另查</td></tr><tr><td>VLSI Technology and Circuits</td><td>器件、工艺与电路交叉</td><td>领域旗舰会议</td><td>见前表</td></tr><tr><td>EDL</td><td>电子器件快速成果</td><td>IEEE Electron Device Letters，短文期刊</td><td>常规稿滚动</td></tr><tr><td>TED</td><td>电子器件研究</td><td>IEEE Transactions on Electron Devices</td><td>常规稿滚动</td></tr><tr><td>OFC</td><td>光通信、光互连</td><td>光通信旗舰会议与展览</td><td>查当届 CFP</td></tr><tr><td>CLEO</td><td>激光、光学与光子学</td><td>重要光学会议</td><td>查当届 CFP</td></tr><tr><td>Optica</td><td>高影响力光学与光子学研究</td><td>Optica Publishing Group 期刊</td><td>常规稿滚动</td></tr></tbody></table><p>Optica 既是学会名称，也是期刊名称，检索时注意区分。会议普通论文、post-deadline paper、教程、竞赛和展览的入口也不能混用。</p><h2 id="如何理解-ccf-推荐目录" tabindex="-1">如何理解 CCF 推荐目录 <a class="header-anchor" href="#如何理解-ccf-推荐目录" aria-label="Permalink to &quot;如何理解 CCF 推荐目录&quot;">​</a></h2><p>中国计算机学会（CCF）的推荐目录按计算机领域分类、按版本列出推荐国际会议和期刊。它适合了解计算机领域的共同体认可度，不覆盖所有 IC 核心领域；不能因 ISSCC、IEDM 等不在某个计算机目录中就判断其学术价值。</p><p>使用时应在 <a href="https://www.ccf.org.cn/Academic_Evaluation/By_category/" target="_blank" rel="noreferrer">CCF 官方目录</a>核对名称、类别和版本，再查所在院校当年的认定办法。CCF、JCR 分区、中科院分区和学校目录不是同一体系；录用率也不是跨领域可直接比较的“难度分数”。</p><h2 id="如何开始跟踪" tabindex="-1">如何开始跟踪 <a class="header-anchor" href="#如何开始跟踪" aria-label="Permalink to &quot;如何开始跟踪&quot;">​</a></h2><p>先给一个方向选两种会议和一种期刊，精读近两三年与你的问题相关的工作，而非从头下载全部论文。把征稿日期、论文篇幅、匿名规则、数据与代码政策记到日历；先与导师确认工作成熟度，再谈投稿目标。具体稿件准备见<a href="/shanghaitech-ic-wiki-dev.github.io/research-guide/writing">学术写作</a>。</p><h2 id="官方入口" tabindex="-1">官方入口 <a class="header-anchor" href="#官方入口" aria-label="Permalink to &quot;官方入口&quot;">​</a></h2><ul><li><a href="https://www.isscc.org/" target="_blank" rel="noreferrer">ISSCC</a> · <a href="https://www.vlsisymposium.org/" target="_blank" rel="noreferrer">VLSI Symposium</a> · <a href="https://sscs.ieee.org/" target="_blank" rel="noreferrer">IEEE Solid-State Circuits Society</a></li><li><a href="https://www.sigarch.org/" target="_blank" rel="noreferrer">ACM SIGARCH</a> · <a href="https://www.dac.com/" target="_blank" rel="noreferrer">DAC</a> · <a href="https://iccad.com/" target="_blank" rel="noreferrer">ICCAD</a> · <a href="https://www.date-conference.com/" target="_blank" rel="noreferrer">DATE</a> · <a href="https://www.aspdac.com/" target="_blank" rel="noreferrer">ASP-DAC</a></li><li><a href="https://www.isfpga.org/" target="_blank" rel="noreferrer">ACM FPGA</a> · <a href="https://www.fccm.org/" target="_blank" rel="noreferrer">FCCM</a> · <a href="https://fpl.org/" target="_blank" rel="noreferrer">FPL</a></li><li><a href="https://www.ieee-iedm.org/" target="_blank" rel="noreferrer">IEDM</a> · <a href="https://eds.ieee.org/" target="_blank" rel="noreferrer">IEEE Electron Devices Society</a></li><li><a href="https://www.ofcconference.org/" target="_blank" rel="noreferrer">OFC</a> · <a href="https://www.cleoconference.org/" target="_blank" rel="noreferrer">CLEO</a> · <a href="https://www.optica.org/" target="_blank" rel="noreferrer">Optica</a></li></ul>',19)])])}const f=d(o,[["render",i]]);export{p as __pageData,f as default};
